import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"5.1 建立可查看的记忆","description":"记住有用的信息，并说明来源和用途。","frontmatter":{"title":"5.1 建立可查看的记忆","description":"记住有用的信息，并说明来源和用途。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-5/5-1.md","filePath":"delivery/stage-5/5-1.md","lastUpdated":1793859143000}'),r={name:"delivery/stage-5/5-1.md"};function o(s,e,n,d,_,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_5-1-建立可查看的记忆" tabindex="-1">5.1 建立可查看的记忆 <a class="header-anchor" href="#_5-1-建立可查看的记忆" aria-label="Permalink to &quot;5.1 建立可查看的记忆&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让 Hearth 记住对用户真正有用的信息，并能说明每条记忆从哪里来、为什么被使用。用户必须能查看和修改这些记忆。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>记录用户事实、项目背景、偏好、承诺和过去任务经验，但只记录有来源的信息。</li><li>每条记忆都标明来源、时间、可信程度、适用范围和敏感程度。</li><li>提供记忆浏览器，用户能看到记住了什么、最近在哪里被使用。</li><li>任务使用记忆时，说明用了哪几条以及为什么相关，避免黑箱召回。</li><li>只把任务需要的最小背景交给执行过程，不把所有记忆一次性塞进去。</li><li>用户修改或删除记忆后，后续任务立即使用新版本。</li></ol>',5)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
